@Test
public void testPurgeUser() {
    final String testUsername = "testUser";
    final String testPassword = "testPassword";
    // setup broker
    final Map<String, Object> brokerAttributes = Map.of("name", "Broker", Broker.MODEL_VERSION, BrokerModel.MODEL_VERSION, Broker.DURABLE, true);
    _brokerImpl = new BrokerImpl(brokerAttributes, _systemConfig);
    _brokerImpl.open();
    // setup auth provider with testuser
    final Map<String, Object> authProviderAttributes = Map.of(ConfiguredObject.NAME, "testAuthProvider", ConfiguredObject.TYPE, "Simple");
    final SimpleAuthenticationManager authenticationProvider = new SimpleAuthenticationManager(authProviderAttributes, _brokerImpl);
    authenticationProvider.create();
    authenticationProvider.addUser(testUsername, testPassword);
    // setup preference owned by testuser
    final UUID preferenceId = randomUUID();
    final Map<String, Object> preferenceAttributes = Map.of(Preference.ID_ATTRIBUTE, preferenceId, Preference.NAME_ATTRIBUTE, "testPref", Preference.TYPE_ATTRIBUTE, "X-testPrefType", Preference.VALUE_ATTRIBUTE, Collections.EMPTY_MAP);
    final Subject testUserSubject = new Subject();
    testUserSubject.getPrincipals().add(new AuthenticatedPrincipal(new UsernamePrincipal(testUsername, authenticationProvider)));
    testUserSubject.setReadOnly();
    final Collection<Preference> preferences = Set.of(PreferenceFactory.fromAttributes(_brokerImpl, preferenceAttributes));
    Subject.doAs(testUserSubject, (PrivilegedAction<Void>) () -> {
        try {
            _brokerImpl.getUserPreferences().updateOrAppend(preferences).get(10, TimeUnit.SECONDS);
        } catch (InterruptedException | ExecutionException | TimeoutException e) {
            e.printStackTrace();
            fail("Failed to put preference:");
        }
        return null;
    });
    // test pre-conditions
    final Collection<Preference> preferencesBeforePurge = getPreferencesAs(testUserSubject);
    assertEquals(1, (long) preferencesBeforePurge.size(), "Unexpected number of preferences before userPurge");
    assertEquals(preferenceId, preferencesBeforePurge.iterator().next().getId(), "Unexpected preference before userPurge");
    assertTrue(authenticationProvider.getUsers().containsKey(testUsername), "User was not valid before userPurge");
    _brokerImpl.purgeUser(authenticationProvider, testUsername);
    // test post-conditions
