    _queue.checkMessageStatus();
    while (_consumerTarget.processPending()) ;
    assertEquals(2, (long) _consumerTarget.getMessages().size(), "Message which was valid was not received");
    assertEquals(messageA.getMessageHeader().getMessageId(), _consumerTarget.getMessages().get(1).getMessage().getMessageHeader().getMessageId(), "Wrong message received");
}

