@Test
void durableTrueConversion() {
    final AMQMessageHeader header = mock(AMQMessageHeader.class);
    final InternalMessage originalMessage = createTestMessage(header, null, true);
    final AMQMessage convertedMessage = _messageConverter.convert(originalMessage, _addressSpace);
    assertEquals(BasicContentHeaderProperties.PERSISTENT, (long) convertedMessage.getContentHeaderBody().getProperties().getDeliveryMode(), "Unexpected delivery mode");
    assertTrue(convertedMessage.isPersistent(), "Unexpected persistence of message");
    assertTrue(convertedMessage.getStoredMessage().getMetaData().isPersistent(), "Unexpected persistence of meta data");
}

@Test
void durableFalseConversion() {
    final AMQMessageHeader header = mock(AMQMessageHeader.class);
    final InternalMessage originalMessage = createTestMessage(header, null, false);
    final AMQMessage convertedMessage = _messageConverter.convert(originalMessage, _addressSpace);
    assertEquals(BasicContentHeaderProperties.NON_PERSISTENT, (long) convertedMessage.getContentHeaderBody().getProperties().getDeliveryMode(), "Unexpected delivery mode");
    assertFalse(convertedMessage.isPersistent(), "Unexpected persistence of message");
    assertFalse(convertedMessage.getStoredMessage().getMetaData().isPersistent(), "Unexpected persistence of meta data");
}

