@Test
public void testDecideForWildcardLoggerName() {
    final LoggerNameAndLevelFilter filter = new LoggerNameAndLevelFilter("org.apache.qpid.server.*", Level.INFO);
    final ILoggingEvent event = mock(ILoggingEvent.class);
    when(event.getLevel()).thenReturn(Level.INFO);
    when(event.getLoggerName()).thenReturn("org.apache.qpid.server.foo");
    assertEquals(FilterReply.ACCEPT, filter.decide(event), "Unexpected reply for matching logger name and log level");
    when(event.getLoggerName()).thenReturn("org.apache.qpid.foo");
    assertEquals(FilterReply.NEUTRAL, filter.decide(event), "Unexpected reply for non matching logger name but matching log level");
    when(event.getLoggerName()).thenReturn("org.apache.qpid.server.foo");
    when(event.getLevel()).thenReturn(Level.DEBUG);
    assertEquals(FilterReply.NEUTRAL, filter.decide(event), "Unexpected reply for matching logger name but non matching log level");
}

